-- Prepared for review; not applied remotely. No sightings are seeded.
create table public.community_municipalities (
 id text primary key check (id ~ '^35[0-9]{5}$'),
 name text not null, uf text not null check (uf = 'SP'),
 latitude double precision not null check (latitude between -26 and -19),
 longitude double precision not null check (longitude between -54 and -44),
 source_url text not null
);
alter table public.community_municipalities enable row level security;
revoke all on public.community_municipalities from anon, authenticated;
grant select on public.community_municipalities to anon, authenticated;
create policy municipality_read on public.community_municipalities for select to anon, authenticated using (true);
-- MIT dataset; exact provenance and license also shipped in assets/data/.

create table public.community_sightings (
 id uuid primary key,
 owner_id uuid not null references auth.users(id),
 municipality_id text not null references public.community_municipalities(id),
 observed_on date not null check (observed_on between date '1900-01-01' and current_date),
 species_label text check (length(species_label) between 1 and 120 and species_label = btrim(species_label)),
 identification_origin text not null check (identification_origin in ('unknown','user','ai')),
 notes text not null default '' check (length(notes) <= 2000),
 status text not null default 'draft' check (status in ('draft','published','deleting')),
 photo_path text not null unique,
 created_at timestamptz not null default now(),
 check ((identification_origin = 'unknown') = (species_label is null)),
 check (photo_path = owner_id::text || '/' || id::text || '/photo.png')
);
create index community_public_page on public.community_sightings (created_at desc, id desc) where status = 'published';
create index community_municipal_page on public.community_sightings (municipality_id, created_at desc, id desc) where status = 'published';
create index community_author_page on public.community_sightings (owner_id, created_at desc, id desc);
alter table public.community_sightings enable row level security;
revoke all on public.community_sightings from anon, authenticated;
grant select on public.community_sightings to anon, authenticated;
grant insert, update, delete on public.community_sightings to authenticated;
create policy sightings_read on public.community_sightings for select to anon, authenticated
 using (status = 'published' or (owner_id = (select auth.uid()) and (select auth.jwt()->>'is_anonymous') = 'false'));
create policy sightings_insert on public.community_sightings for insert to authenticated
 with check (owner_id = (select auth.uid()) and (select auth.jwt()->>'is_anonymous') = 'false' and status = 'draft');
create policy sightings_update on public.community_sightings for update to authenticated
 using (owner_id = (select auth.uid()) and (select auth.jwt()->>'is_anonymous') = 'false')
 with check (owner_id = (select auth.uid()) and (select auth.jwt()->>'is_anonymous') = 'false');
create policy sightings_delete on public.community_sightings for delete to authenticated
 using (owner_id = (select auth.uid()) and (select auth.jwt()->>'is_anonymous') = 'false' and status in ('draft','deleting'));

 values ('community-photos','community-photos',false,4194304,array['image/png']);
-- Policies apply only to this dedicated private bucket. No overwrite/upsert.
create policy community_photo_read on storage.objects for select to anon, authenticated
 using (bucket_id = 'community-photos' and exists (
  select 1 from public.community_sightings s where s.photo_path = name
   and (s.status = 'published' or (s.owner_id = (select auth.uid()) and (select auth.jwt()->>'is_anonymous') = 'false'))
 ));
create policy community_photo_insert on storage.objects for insert to authenticated
 with check (bucket_id = 'community-photos' and (select auth.jwt()->>'is_anonymous') = 'false'
  and exists (select 1 from public.community_sightings s
   where s.photo_path = name and s.owner_id = (select auth.uid()) and s.status = 'draft'));
create policy community_photo_delete on storage.objects for delete to authenticated
 using (bucket_id = 'community-photos' and (select auth.jwt()->>'is_anonymous') = 'false'
  and exists (select 1 from public.community_sightings s
   where s.photo_path = name and s.owner_id = (select auth.uid()) and s.status in ('draft','deleting')));

-- Invoker, fixed search_path: no authorization bypass. Storage SELECT policy
-- above lets the author see their own object when publishing/removing a draft.
create function public.community_sighting_guard() returns trigger
 language plpgsql security invoker set search_path = '' as $$
begin
 if TG_OP = 'UPDATE' then
  if new.id <> old.id or new.owner_id <> old.owner_id or new.photo_path <> old.photo_path
     or new.created_at <> old.created_at then
   raise exception 'Sighting identity is immutable' using errcode = '23514';
  end if;
  if old.status = 'deleting' and new.status <> 'deleting'
     or old.status = 'published' and new.status = 'draft' then
   raise exception 'Invalid publication transition' using errcode = '23514';
  end if;
 end if;
 if TG_OP = 'DELETE' then
  if exists (select 1 from storage.objects where bucket_id = 'community-photos' and name = old.photo_path) then
   raise exception 'Remove image using Storage API before removing row' using errcode = '23514';
  end if;
  return old;
 end if;
 if new.status = 'published' and not exists (
  select 1 from storage.objects where bucket_id = 'community-photos' and name = new.photo_path
 ) then
  raise exception 'Upload image before publication' using errcode = '23514';
 end if;
 return new;
end $$;
revoke all on function public.community_sighting_guard() from public, anon, authenticated;
create trigger community_sighting_lifecycle before update or delete on public.community_sightings
 for each row execute function public.community_sighting_guard();
